use vstd::prelude::*;

verus! {
    /// Given a non‐negative 8‐bit integer `n`, produce a Vec<f64> of length exactly `n`.
    /// We push the value 0.0 on each iteration, but the actual values are not constrained;
    /// only the final length matters.
    pub fn empty(n: u8) -> (result: Vec<f64>)
        ensures
            // The resulting vector has length exactly equal to the input `n`.
            result.len() == n as usize
    {
        // We'll build the vector incrementally.
        let mut v: Vec<f64> = Vec::new();
        // Convert the target length to a `usize` so we can compare with `v.len()`.
        let target: usize = n as usize;

        // Repeatedly push until we reach the desired length.
        // Invariant: The current length is never more than the target.
        // Decreases: target − current length, ensuring strict progress toward termination.
        while v.len() < target
            invariant
                v.len() <= target,
            decreases
                target - v.len()
        {
            v.push(0.0);
        }

        // Return the filled vector.
        result = v;
    }
}